tool_input.command:
SP="/private/tmp/claude-501/-Users-testuser-work-dotclaude/0e9e6685-e540-405e-90c3-77258ea83319/scratchpad"
if [ -s "$SP/payload-capture.jsonl" ]; then
  echo "=== 포획 성공! PostToolUse 페이로드의 최상위 키 ==="
  tail -1 "$SP/payload-capture.jsonl" | node -e "let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{const j=JSON.parse(d);
    console.log('최상위 키:', Object.keys(j).join(', '));
    console.log('');
    console.log('tool_response 존재?:', 'tool_response' in j, '| 타입:', typeof j.tool_response);
    if (j.tool_response && typeof j.tool_response==='object') console.log('tool_response 하위 키:', Object.keys(j.tool_response).join(', '));
    console.log('최상위 stdout 존재?:', 'stdout' in j, '| 최상위 stderr 존재?:', 'stderr' in j);
    console.log('');
    console.log('--- stderr 내용 (중첩 경로) ---');
    console.log(JSON.stringify(j.tool_response?.stderr ?? '(없음)').slice(0,200));
  })"
else
  echo "포획 실패 — 훅이 세션 중간 설정 변경을 못 읽었을 수 있음"
fi

cd /Users/testuser/work/dotclaude
SP="/private/tmp/claude-501/-Users-testuser-work-dotclaude/0e9e6685-e540-405e-90c3-77258ea83319/scratchpad"
node -e "
const fs=require('fs');
const p='.claude/settings.local.json';
const s=JSON.parse(fs.readFileSync(p,'utf8'));
const SP='$SP';
delete s.hooks.PostToolUse;                       // Bash 캡처는 목적 달성 — 제거
s.hooks.Stop = [{ matcher:'', hooks:[{ type:'command', command: 'cat >> \"'+SP+'/stop-capture.jsonl\"' }] }];
s.hooks.Notification = [{ matcher:'', hooks:[{ type:'command', command: 'cat >> \"'+SP+'/notification-capture.jsonl\"' }] }];
fs.writeFileSync(p, JSON.stringify(s,null,2));
console.log('PostToolUse 캡처 제거 / Stop + Notification 캡처 설치');
console.log('설치된 임시 훅:', Object.keys(s.hooks).join(', '));
"
echo; echo "=== 이 세션 종료 후 복구용 백업 확인 ==="; ls -l "$SP/settings.local.json.bak"
